head.script:
// 상장관련공통함수
// 화면 리사이징

scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.setCode();
        $c.cm.fn_com_isu(txb_ISUR_CD, txb_COM_NM);
        Grd_com_isur.style.zIndex = 30;
        $c.cm.PanelToGroupBox(panel_1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35404.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description btn_Search 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35404.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts1_OnLoadCompleted
 * @description dts1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts1_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35404.dts1_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts1_OnLoadError
 * @description dts1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts1_OnLoadError = async function() {
    try {
        await $c.win.alert(dts1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35404.dts1_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function() {
    try {
        // IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
        //  JongmokSearch(txb_ISUR_CD, txb_COM_NM, SECUGRP_ID_ST, js_market, "A");
        $c.stockSearch.JongmokSearch3(txb_ISUR_CD, txb_COM_NM, SECUGRP_ID_ST, js_market, "A");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35404.btn_ISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35404.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35404.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35404.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35404.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name dts_DEP_CD_OnLoadCompleted
 * @description dts_DEP_CD 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DEP_CD_OnLoadCompleted = function(rowcount) {
    try {
        cmb_DEP_CD.setValue('');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35404.dts_DEP_CD_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_OnLoadCompleted
 * @description dts_EMP_NO 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_OnLoadCompleted = function(rowcount) {
    try {
        cmb_EMP_NO.setValue('');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35404.dts_EMP_NO_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name cmb_DEP_CD_onselchange
 * @description cmb_DEP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_onselchange = function() {
    try {
        scwin.gDepCd = cmb_DEP_CD.getValue();
        if (scwin.gDepCd === '') {
            cmb_EMP_NO.setValue('');
        }
        dts_EMP_NO.UseFilter = true;
        dts_EMP_NO.Filter();
        dts_EMP_NO.sort("DEP_CD", 0);
        // dts_EMP_NO.sort(); // W-Craft 주석처리
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35404.cmb_DEP_CD_onselchange" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_OnFilter
 * @description EMP NO On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_OnFilter = function(row) {
    try {
        if (scwin.gDepCd === "") {
            return true;
        } else {
            if (dts_EMP_NO.getCellData(row, "DEP_CD") === scwin.gDepCd || dts_EMP_NO.getCellData(row, "DEP_CD") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35404.dts_EMP_NO_OnFilter" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "종류주식-주식수요건", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35404.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35404.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnUserColor
 * @description grd Grid On User Color 처리
 * @param {Number} row 행 인덱스
 * @param {String} eventId eventId
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnUserColor = function(row, eventId) {
    try {
        const colorYellow = "#FFFFCC";
        const colorGreen = "#CCFFCC";
        const colorRed = "#FFCCCC";
        if (eventId === "acolor7" && (dts1.getCellData(row, "ADMISU_DESIGN_YN") === "해당")) {
            return colorYellow;
        }
        if (eventId === "acolor12" && (dts1.getCellData(row, "ADMISU_RELEAS_YN") === "해당")) {
            return colorGreen;
        }
        if (eventId === "acolor15" && (dts1.getCellData(row, "DELIST_YN") === "해당")) {
            return colorRed;
        }
        if (row % 2 === 0) return "#f2f5f9";

        else return "#ffffff";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35404.grd_Grid_OnUserColor" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35404.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35404.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35404.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35404.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35404.Grd_com_isur_OnKillFocus" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    const sbmOptions = {
        id : "sbm_dts_DEP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_DEP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_EMP_NO",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EMP_NO=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    cmb_DEP_CD.setValue('');
    cmb_EMP_NO.setValue('');

    /*
    		dts_DepCd.DataID = "/AdminAndDlstedDetection.do?method=getComboList&For=DR_K&outputMessageId=AADD_OUT_COMBO";
    		dts_DepCd.Reset();

    		dts_EmpNo.DataID = "/AdminAndDlstedDetection.do?method=getComboList&For=ER_K&outputMessageId=AADD_OUT_COMBO";
    		dts_EmpNo.Reset();	*/

};

/**
     * @method
     * @name listSync
     * @description 종류주식 주주수요건 검색
     * @returns {Promise<void>}
     * @hidden N
     */
scwin.listSync = async function() {
    const isu_cd = txb_ISUR_CD.getValue();
    const team_cd = $c.cp.valueOfIndex(cmb_DEP_CD, "VALUE", cmb_DEP_CD.getSelectedIndex());
    const charge_id = $c.cp.valueOfIndex(cmb_EMP_NO, "VALUE", cmb_EMP_NO.getSelectedIndex());
    const sbmOptions = {
        id : "sbm_dts1",
        action : "/AdminAndDlstedDetection.do",
        ref : "",
        target : "dts1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
